INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (3001100, "2024/10/31 12:00:00", 2.1, 1, "ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか", 130011, 3001, -416.5, "2030/01/01 14:59:59", 100, 0, "ヤマト", 2);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (3001101, "2024/10/31 12:00:00", 5.68, 4, "他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか", 130011, 3001, -416.5, "2030/01/01 14:59:59", 101, 0, "ヤマト", 2);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (3001102, "2024/10/31 12:00:00", 0, 1, "なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。", 130011, 3001, -416.5, "2030/01/01 14:59:59", 102, 0, "ヤマト", 1);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (3002100, "2024/10/31 12:00:00", 0, 1, "え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？", 130211, 3002, -416.5, "2030/01/01 14:59:59", 100, 0, "フブキ", 1);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (3002101, "2024/10/31 12:00:00", 0, 1, "ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡", 130211, 3002, -416.5, "2030/01/01 14:59:59", 101, 0, "フブキ", 1);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (3002102, "2024/10/31 12:00:00", 8.53, 5, "へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ", 130211, 3002, -416.5, "2030/01/01 14:59:59", 102, 0, "フブキ", 2);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (3002103, "2024/10/31 12:00:00", 5.67, 7, "なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？", 130211, 3002, -416.5, "2030/01/01 14:59:59", 103, 0, "フブキ", 1);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (3002104, "2024/10/31 12:00:00", 0, 1, "ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？", 130211, 3002, -416.5, "2030/01/01 14:59:59", 104, 0, "フブキ", 1);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (3002300, "2024/10/31 12:00:00", 0, 3, "あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？", 130211, 3004, -416.5, "2030/01/01 14:59:59", 300, 0, "フブキ", 3);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (3002400, "2024/10/31 12:00:00", 0, 7, "ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡", 130211, 3005, -416.5, "2030/01/01 14:59:59", 301, 0, "フブキ", 7);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (3003200, "2024/10/31 12:00:00", 4.4, 2, "きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪", 130211, 3003, -416.5, "2030/01/01 14:59:59", 200, 0, "フブキ", 1);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (3003201, "2024/10/31 12:00:00", 0, 7, "は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ", 130211, 3003, -416.5, "2030/01/01 14:59:59", 201, 0, "フブキ", 7);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (3003202, "2024/10/31 12:00:00", 5.6, 1, "お兄さんってば、ぼくがいないと\nほんとザッコザコだよね～\nもっと感謝しろし～♪", 130211, 3003, -416.5, "2030/01/01 14:59:59", 202, 0, "フブキ", 2);
